corrected_code:
const express = require('express');
const { requireStagingAccess } = require('../auth');
const { BenchmarkReport } = require('../models/benchmark');

const app = express();

app.get('/staging/benchmarks/reports/:reportId', requireStagingAccess, async (req, res) => {
  const { reportId } = req.params;

  const report = await BenchmarkReport.findOne({
    where: {
      id: reportId,
      tenantId: req.user.tenantId
    }
  });

  if (!report) {
    return res.status(404).json({ error: 'Benchmark report not found or access denied' });
  }

  res.json({
    reportId: report.id,
    targetService: report.serviceName,
    queryPlans: report.executionPlans,
    metrics: report.latencyMetrics
  });
});

module.exports = app;
